def compute(vars):
    current = vars["v1"]
    previous = vars["v2"]

    if previous == 0:
        return None

    decrease = previous - current
    rate_of_decrease = decrease / previous

    return {
        "value": rate_of_decrease,
        "trace": {
            "current_value": current,
            "previous_value": previous,
            "decrease": decrease,
            "rate_of_decrease": rate_of_decrease,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": None
            }
        }
    }
